#!/usr/bin/env bash
set -euo pipefail
WWW='https://www.ball46.com'; DIRECT='https://ball46-production.mccarey-supon.workers.dev'; OUT='/tmp/b46-scorebar-final-verify'; rm -rf "$OUT"; mkdir -p "$OUT"
python3 - <<'PY'
import base64,hashlib,json,os,urllib.request,pathlib
A=os.environ['CLOUDFLARE_ACCOUNT_ID'];T=os.environ['CLOUDFLARE_API_TOKEN'];h={'Authorization':f'Bearer {T}','Accept':'application/json'};api=f'https://api.cloudflare.com/client/v4/accounts/{A}';s='ball46-production'
def get(u):
 with urllib.request.urlopen(urllib.request.Request(u,headers=h),timeout=30) as r:return json.load(r)
d=get(f'{api}/workers/scripts/{s}/deployments')['result']['deployments'][0];vs=d.get('versions') or []
if len(vs)!=1 or float(vs[0].get('percentage',0))!=100: raise SystemExit('MIXED_DEPLOYMENT')
vid=vs[0]['version_id'];v=get(f'{api}/workers/workers/{s}/versions/{vid}?include=modules')['result'];mods=v.get('modules') or [];sha=hashlib.sha256(base64.b64decode(mods[0]['content_base64'])).hexdigest()
if vid!='07d2ec0d-37bd-43bb-bb98-b5dc6e05d788': raise SystemExit('VERSION_MOVED:'+vid)
if sha!='f961c641bb726f042f3d2e4a53e23363f68aa8497092f8071900b398cfb076ed': raise SystemExit('RUNTIME_BAD:'+sha)
print('FINAL_RUNTIME_LOCK_PASS',vid,sha)
PY
nonce="${GITHUB_RUN_ID:-manual}-$(date +%s%N)"
for rel in dashboard-v2-stage3.js singlepage-workspace-343.css index.html; do curl -fsS -L --retry 4 --retry-all-errors --max-time 30 -H 'Cache-Control: no-cache,no-store' -H 'Pragma: no-cache' "$DIRECT/$rel?final=$nonce-$RANDOM" -o "$OUT/$rel"; done
printf '%s  %s\n' '83d1c17b60fcf122fe083245a5e09a587c1bf06dc0dceae34a02106fb42a023a' dashboard-v2-stage3.js 'a8186bd85a9c9f884d992ecd24fad7b80820fdc92ae6cace82034bdc92c566a1' singlepage-workspace-343.css '464c7f603b6449308e322071ecd056d436bd0be3c4cdca8b2b7c13c52d13cd4f' index.html | (cd "$OUT" && sha256sum -c -)
grep -Fq 'BALL46_SCOREBAR_SIGNAL_FLOW_20260928' "$OUT/dashboard-v2-stage3.js"; grep -Fq 'data-scorebar-pending-signal' "$OUT/dashboard-v2-stage3.js"; grep -Fq 'data:image/webp;base64' "$OUT/singlepage-workspace-343.css"; grep -Fq '343-scorebar-bg-pending-20260928a' "$OUT/index.html"; echo FINAL_TARGET_ASSETS_PASS
for ep in board signals statistics; do curl -fsS -L --retry 4 --retry-all-errors --max-time 30 "$WWW/api/engine/$ep?final=$nonce" -o "$OUT/$ep.json"; done
python3 - <<'PY'
import json,pathlib
r=pathlib.Path('/tmp/b46-scorebar-final-verify');allowed={'WIN','HALF_WIN','LOSS','HALF_LOSS','PUSH','DRAW'}
for n in ['board','signals','statistics']:
 j=json.load(open(r/f'{n}.json'))
 if j.get('ok') is not True: raise SystemExit('API_BAD:'+n)
s=json.load(open(r/'signals.json'));t=json.load(open(r/'statistics.json'));sett=[x for x in t.get('rows',[]) if str(x.get('status','')).upper()=='SETTLED' and str(x.get('result','')).upper() in allowed];sett.sort(key=lambda x:x.get('settledAt') or x.get('createdAt') or 0,reverse=True);pend=[x for x in s.get('signals',[]) if str(x.get('status','')).upper()=='PENDING'];pend.sort(key=lambda x:(x.get('mirrorMinute') if x.get('mirrorMinute') is not None else x.get('minute') if x.get('minute') is not None else x.get('entryMinute') if x.get('entryMinute') is not None else -1,x.get('createdAt') or 0),reverse=True);(r/'expected.json').write_text(json.dumps({'settled':sett[:6],'pending':pend[:4]},ensure_ascii=False));print('FINAL_API_PASS',{'settled':len(sett),'pending':len(pend),'fixtures':len(json.load(open(r/'board.json')).get('fixtures',[]))})
PY
chrome=$(command -v google-chrome || command -v chromium || command -v chromium-browser || true); [ -n "$chrome" ] || exit 1
"$chrome" --headless=new --no-sandbox --disable-gpu --hide-scrollbars --window-size=1440,900 --remote-debugging-port=9899 --user-data-dir="$OUT/chrome" "$WWW/?finalscorebar=$nonce" >"$OUT/chrome.log" 2>&1 & CPID=$!; trap 'kill $CPID 2>/dev/null||true' EXIT
for i in $(seq 1 80); do curl -fsS http://127.0.0.1:9899/json > "$OUT/pages.tmp" 2>/dev/null && python3 -c "import json;x=json.load(open('$OUT/pages.tmp'));assert any(p.get('type')=='page' and p.get('webSocketDebuggerUrl') for p in x)" 2>/dev/null && { mv "$OUT/pages.tmp" "$OUT/pages.json"; break; }; sleep .5; done
cat > "$OUT/check.js" <<'NODE'
const fs=require('fs'),pages=JSON.parse(fs.readFileSync('/tmp/b46-scorebar-final-verify/pages.json')),p=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl),exp=JSON.parse(fs.readFileSync('/tmp/b46-scorebar-final-verify/expected.json'));if(!p)throw Error('NO_PAGE');const map=r=>r==='WIN'?'WIN':r==='HALF_WIN'?'WIN ½':r==='LOSS'?'LOSS':r==='HALF_LOSS'?'LOSS ½':(r==='PUSH'||r==='DRAW')?'DRAW':r;const ws=new WebSocket(p.webSocketDebuggerUrl);let id=0,q=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&q.has(m.id)){const z=q.get(m.id);q.delete(m.id);m.error?z.j(Error(JSON.stringify(m.error))):z.r(m.result)}};const call=(method,params={})=>new Promise((r,j)=>{const n=++id;q.set(n,{r,j});ws.send(JSON.stringify({id:n,method,params}))}),sleep=ms=>new Promise(r=>setTimeout(r,ms));async function ev(x){const z=await call('Runtime.evaluate',{expression:x,returnByValue:true,awaitPromise:true});if(z.exceptionDetails)throw Error(JSON.stringify(z.exceptionDetails));return z.result.value}async function wait(x,t=45000){const s=Date.now();while(Date.now()-s<t){try{if(await ev(x))return}catch{}await sleep(250)}throw Error('WAIT '+x)};(async()=>{await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});await call('Runtime.enable');await call('Page.enable');await call('Page.bringToFront');await wait(`document.readyState==='complete'`);await wait(`document.querySelectorAll('[data-scorebar-signal-result]').length===6`);await sleep(1000);const d=await ev(`(()=>{const c=[...document.querySelectorAll('[data-workspace-scorebar-slot] .workspace-scorebar-grid>div')];return{count:c.length,left:c.slice(0,6).map(x=>({result:x.getAttribute('data-scorebar-signal-result')||'',bg:getComputedStyle(x).backgroundImage,w:x.getBoundingClientRect().width,h:x.getBoundingClientRect().height,text:x.innerText})),right:c.slice(6).map(x=>({id:x.getAttribute('data-scorebar-pending-signal')||'',pending:x.hasAttribute('data-scorebar-pending-signal'),placeholder:x.classList.contains('placeholder'),live:x.classList.contains('workspace-scorebar-live'),text:x.innerText,w:x.getBoundingClientRect().width,h:x.getBoundingClientRect().height})),slot:getComputedStyle(document.querySelector('[data-workspace-scorebar-slot]')).display,odds:!!window.NOMAD343_ODDS,favicon:!!document.querySelector('link[data-ball46-favicon="20260928"]'),overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+2}})()`);const wl=exp.settled.map(x=>map(String(x.result||'').toUpperCase()));if(d.count!==10||JSON.stringify(d.left.map(x=>x.result))!==JSON.stringify(wl))throw Error('LEFT_BAD');for(const x of d.left)if(!x.bg.includes('data:image/webp;base64')||Math.abs(x.h-58)>.5)throw Error('LEFT_IMAGE_SIZE_BAD');const wp=exp.pending.map(x=>String(x.id||x.fixtureId||'')),real=d.right.filter(x=>x.pending);if(JSON.stringify(real.map(x=>x.id))!==JSON.stringify(wp)||d.right.some(x=>x.live)||d.right.filter(x=>x.placeholder).length!==4-wp.length)throw Error('RIGHT_PENDING_BAD '+JSON.stringify({got:real.map(x=>x.id),want:wp}));for(const x of real)if(!x.text.includes('PENDING')||Math.abs(x.h-58)>.5)throw Error('RIGHT_DETAIL_BAD');if(!d.odds||!d.favicon||d.overflow)throw Error('DESKTOP_BAD');await call('Emulation.setDeviceMetricsOverride',{width:390,height:850,deviceScaleFactor:1,mobile:false});await call('Page.reload',{ignoreCache:true});await wait(`document.readyState==='complete'`);await sleep(2500);const m=await ev(`(()=>({slot:getComputedStyle(document.querySelector('[data-workspace-scorebar-slot]')).display,odds:!!window.NOMAD343_ODDS,favicon:!!document.querySelector('link[data-ball46-favicon="20260928"]'),overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+2}))()`);if(m.slot!=='none'||!m.odds||!m.favicon||m.overflow)throw Error('MOBILE_BAD');console.log('FINAL_BROWSER_PASS',JSON.stringify({left:wl,pending:wp,placeholders:4-wp.length,size:[d.left[0]?.w,d.left[0]?.h],mobile:m.slot}));ws.close();process.exit(0)})().catch(e=>{console.error(e);process.exit(1)});
NODE
node "$OUT/check.js"
kill "$CPID" 2>/dev/null||true; trap - EXIT
echo BALL46_SCOREBAR_FINAL_VERIFY_SUCCESS_NO_DEPLOY
